// Static design mock. Reads only acme-data.js (generated by fixtures.py). No network, no logbook, no agent.
const M = ACME.model;
const SRC = ACME.source;
const ENVS = ["local", "test", "staging", "production"].filter((e) => M.environments[e]);
const OPS = Object.values(M.operations);
const THINGS = Object.values(M.things);
const S = { scenario: "none", env: "all" };

const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const comp = (name) => `<span class="comp" title="Component this section maps to (F2 §4)">${esc(name)}</span>`;
const chip = (text, cls = "") => `<span class="chip ${cls}">${esc(text)}</span>`;
const plain = (text, cls = "") => `<span class="chip plain ${cls}">${esc(text)}</span>`;
const link = (href, text) => `<a href="${href}">${esc(text)}</a>`;
const card = (title, body, c = "", extra = "") => `<section class="card ${extra}">${c ? comp(c) : ""}${title ? `<h2>${title}</h2>` : ""}${body}</section>`;
const table = (heads, rows) => `<div class="scroll"><table><thead><tr>${heads.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;

// ---- links: every declaration has exactly one URL (F2 §5 link rules)
const L = {
  thing: (t) => `#/thing/${t}`, op: (o) => `#/op/${o}`, machine: (t) => `#/thing/${t}/machine`,
  event: (t, e) => `#/thing/${t}/event/${e}`, env: (e) => `#/env/${e}`, board: () => "#/work",
  value: (v) => `#/values#${v}`, role: (r) => `#/roles#${r}`, error: (e) => `#/errors#${e}`, journey: (j) => `#/journeys#${slug(j)}`,
  world: (w) => `#/worlds#${w}`,
};
const slug = (s) => s.replace(/\s+/g, "-");
const opLink = (o) => `<a href="${L.op(o)}"><code>${esc(o)}</code></a>`;
const thingOf = (o) => M.operations[o]?.thing;

// ---- value rendering: show exactly what the model says, never more
function valueText(f) {
  const v = f.value || f;
  if (f.ref) return `${link(L.thing(f.ref.split(".")[0]), f.ref)}`;
  const base = v.type === "uint" ? `uint${v.bits}` : v.type === "text" ? `text ≤ ${v.max}` : v.type === "id" ? `id <code>${v.prefix}_…</code>` : v.type === "schema" ? `schema <span class="muted small">(detail not projected)</span>` : v.type;
  return f.named ? `${link(L.value(f.named), f.named)} <span class="muted small">${base}</span>` : base;
}
const fieldsTable = (fields, note) => Object.keys(fields || {}).length
  ? table(["Field", "Value", note || ""], Object.entries(fields).map(([k, f]) => [`<code>${esc(k)}</code>`, valueText(f), f.ref ? plain("refers", "k-ref") : ""]))
  : `<p class="muted">No fields.</p>`;

// ---- derived indexes (pure joins over the model; no new facts)
function eventsOf(thing) {
  const t = M.things[thing]; const moves = t.machine?.moves || {};
  return Object.entries(t.events || {}).map(([name, fields]) => ({
    thing, name, fields,
    moves: Object.entries(moves).filter(([, m]) => m.emits === name).map(([k, m]) => ({ key: k, ...m })),
    ops: OPS.filter((o) => o.move?.emits === name).map((o) => o.name),
    journeys: SRC.journeys.filter((j) => j.steps.some((s) => s.asserts.some((a) => a.kind === "emits" && a.event === name))),
  }));
}
function refusalsOf(op) {
  return op.refusals.map((r) => {
    const t = M.things[op.thing]; const declared = t.errors?.[r];
    const gen = t.machine?.notFrom && r === t.machine.notFrom.error;
    return { name: r, code: M.refusals[r] || "—", exit: declared?.exit ?? (gen ? t.machine.notFrom.exit : r === "NotAllowed" ? 3 : "—"),
      origin: declared ? "declared in errors.ts" : gen ? "generated by the machine (notFrom)" : r === "NotAllowed" ? "generated from allowed roles" : "generated",
      fields: declared?.fields || (gen ? { state: { value: { type: "text", max: 64 } } } : {}) };
  });
}
const journeysFor = (opName) => SRC.journeys.map((j) => ({ j, steps: j.steps.map((s, i) => ({ ...s, i })).filter((s) => s.calls === opName) })).filter((x) => x.steps.length);
const refusalName = (e) => e?.endsWith(".notFrom") ? M.things[e.split(".")[0]]?.machine?.notFrom?.error || e : e;
const handlerFor = (op) => SRC.handlers.find((h) => h === `src/${op.thing}/${op.verb}.ts`);
const roleText = (a) => a.kind === "role" ? link(L.role(a.role), a.role) : a.kind === "role-of" ? `${link(L.role(a.role), a.role)} <span class="muted small">of ${esc(a.path)}</span>` : plain(a.kind);

// ---- evidence (F1 §1 ProofState). Default: unavailable, because this static mock has no logbook.
const STATE_LABEL = { "recorded-pass": "recorded pass", failed: "failed", stale: "stale", unproven: "unproven", unavailable: "unavailable" };
function proof(opName, env) {
  if (S.scenario === "none") return { state: "unavailable", reason: "No logbook is connected to this static mock." };
  const op = M.operations[opName];
  if (opName === "allowance.spend" && (env === "staging" || env === "production"))
    return { state: "stale", illus: true, reason: "budget p95 changed after the recorded pass (illustrative edit)", changed: [{ key: "allowance.spend", was: op.hash, now: "(illustrative new hash)" }] };
  if (opName === "allowance.revoke" && env === "staging") return { state: "failed", illus: true, reason: "latest staging verdict is fail; an older pass exists and is ignored" };
  if (!journeysFor(opName).length) return { state: "unproven", illus: true, reason: "no journey calls this operation" };
  if (env === "production" && !["allowance", "organization", "person", "session", "system"].includes(op.thing)) return { state: "unproven", illus: true, reason: "no verdict row for production" };
  return { state: "recorded-pass", illus: true, reason: "recorded pass; contract unchanged" };
}
const proofChip = (p) => `<span class="cell">${chip(STATE_LABEL[p.state], "s-" + (p.state === "recorded-pass" ? "pass" : p.state))}</span>`;
const scopedEnvs = () => (S.env === "all" ? ENVS : [S.env]);
function evidenceRow(opName) { return scopedEnvs().map((e) => `<a href="${L.op(opName)}#evidence-${e}" title="${esc(proof(opName, e).reason)}">${proofChip(proof(opName, e))}</a>`); }
function countStates(ops) {
  const c = {}; for (const o of ops) for (const e of scopedEnvs()) { const s = proof(o.name, e).state; c[s] = (c[s] || 0) + 1; } return c;
}
const illusNote = () => S.scenario === "none" ? "" : `<p class="small"><span class="chip plain k-illus">Illustration</span> Evidence states on this page are synthetic, chosen to show each state. No verdict here is real.</p>`;
